import com.github.benmanes.caffeine.cache.Ticker
import com.github.blemale.scaffeine.{Cache, Scaffeine}
import scala.concurrent.duration.*

final class RateLimiter(capacity: Int, refillPerSec: Double, ticker: Ticker = Ticker.systemTicker()):
  private val buckets: Cache[String, TokenBucket] =
    Scaffeine().ticker(ticker).expireAfterAccess(10.minutes).build[String, TokenBucket]()

  def allow(clientId: String): Boolean =
    buckets.get(clientId, _ => TokenBucket(capacity, refillPerSec)).tryTake()

  private[gw] def size: Long =
    buckets.cleanUp()
    buckets.estimatedSize()

class RateLimiterSpec extends AnyFunSuite:
  test("evicts buckets idle for more than 10 minutes") {
    val ticker = FakeTicker()
    val rl = RateLimiter(capacity = 5, refillPerSec = 1, ticker)
    rl.allow("a")
    ticker.advance(11.minutes)
    assert(rl.size == 0)
  }

